import { Injectable } from '@angular/core';
import { SecureStorageService } from '../storage/secure-storage.service';
import { BehaviorSubject } from 'rxjs';
import { Router } from '@angular/router';
import { advanceFiler } from '../../../userpanel/interfaces/advance-search.interface';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';
import { CaseDetailResponce } from '../../../adminpanel/interfaces/casebuilder.interface';
import { setUserInfo } from '../../interfaces/login.interface';

@Injectable({
  providedIn: 'root'
})
export class HeaderService {
  Casedetail: CaseDetailResponce | null = null;
  userdetail: setUserInfo | null = null;

  private userDetailLoadPromise: Promise<void> | null = null;

  currentfolder: { nBundleid: string | null; cBundlename: string } = {
    nBundleid: null,
    cBundlename: 'Master bundle'
  };

  isCaseedit = new BehaviorSubject<boolean>(false);
  expandhyper = false;
  casedetal: Record<string, unknown> = {};
  caseName = '';
  currentadminpath = new BehaviorSubject<string>('');

  nCaseid: string | null = null;
  nPresentid: string | null = null;
  isGlobalSearch: boolean = false;

  jFilter: advanceFiler = { cWithin: 'M', cMatchCase: 'C', cSearch: '', cLocation: 'A', contentType: 'All', isGlobalSearch: false } as advanceFiler;
  nSectionid: string | null = null;
  cFoldertype: string | null = null;
  search_within: string | null = null;

  constructor(
    public readonly ss: SecureStorageService,
    private readonly router: Router
  ) {}

  init(): void {
    this.userDetailLoadPromise ??= this.loadUserDetail();
  }

  private async loadUserDetail(): Promise<void> {
    try {
      this.userdetail = await this.ss.getUserInfo();
    } catch (err: unknown) {
      console.error(ErrorHandlerUtil.getErrorMessage(err));
      this.userdetail = null;
    }
  }

  updatePath(newPath: string): void {
    this.currentadminpath.next(newPath);
  }

  updateisCase(val: boolean): void {
    this.isCaseedit.next(val);
  }

  // async caseDetete(mdl: caseDelReq): Promise<boolean> {
  //   try {
  //     const res: any = await firstValueFrom(
  //       this.http.post<caseDelRes>(`${environment.cloudUrl}${environment.coreservice}/case/casedelete`, mdl)
  //     );
  //     if (res && res.msg == 1) {
  //       this.tost.openSnackBar(res.value, '');
  //       return true;
  //     } else {
  //       this.tost.openSnackBar(res.value, '');
  //       return false;
  //     }
  //   } catch (err) {
  //     this.tost.openSnackBar(`Case deletion failed ${err}`, '');
  //     return false;
  //   }
  // }
  goUserHome() {
    this.router.navigate(['user/dashboard'], { replaceUrl: true });
  }

  goAdminHome(): void {
    this.router.navigate(['/admin/dashboard'], { replaceUrl: true });
  }

  getCaseid(): string | null {
    return this.nCaseid;
  }

  resetState(): void {
    this.Casedetail = null;
    this.userdetail = null;
    this.currentfolder = { nBundleid: null, cBundlename: 'Master bundle' };
    this.isCaseedit.next(false);
    this.expandhyper = false;
    this.casedetal = {};
    this.caseName = '';
    this.currentadminpath.next('');
    this.nCaseid = null;
    this.nPresentid = null;
    this.isGlobalSearch = false;
    this.jFilter = { cWithin: 'M', cMatchCase: 'C', cSearch: '', cLocation: 'A', contentType: 'All', isGlobalSearch: false } as advanceFiler;
    this.nSectionid = null;
    this.cFoldertype = null;
    this.search_within = null;
    this.userDetailLoadPromise = null;
  }
}
